def x_main__mutmut_orig() -> int:
    """CLI entry point for the sync service."""
    import argparse
    
    parser = argparse.ArgumentParser(
        description="Zendesk Knowledge Synchronization Service"
    )
    parser.add_argument(
        "--mode",
        choices=["full", "incremental"],
        default="incremental",
        help="Sync mode: full (all articles) or incremental (changes only)",
    )
    parser.add_argument(
        "--since",
        help="ISO 8601 timestamp for incremental sync start point",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Do not download; only report what would be done",
    )
    parser.add_argument(
        "--force",
        action="store_true",
        help="Force fetch all articles, ignoring cache (full mode only)",
    )
    parser.add_argument(
        "--pipeline",
        action="store_true",
        help="Pipeline synced content to codex_digest after sync",
    )
    parser.add_argument(
        "--export-json",
        action="store_true",
        help="Export articles as JSON dataset (default: true for incremental)",
    )
    parser.add_argument(
        "--log-level",
        default="INFO",
        choices=["DEBUG", "INFO", "WARNING", "ERROR"],
        help="Logging level",
    )
    
    args = parser.parse_args()
    
    # Configure logging
    logging.basicConfig(
        level=getattr(logging, args.log_level),
        format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
    )
    
    # Create service and run sync
    service = ZendeskKnowledgeSyncService()
    
    try:
        # Run sync based on mode
        if args.mode == "incremental":
            logger.info("Running incremental sync (changes only)")
            result = service.check_and_pull_incremental(
                since=args.since,
                dry_run=args.dry_run,
            )
        else:
            logger.info("Running full sync")
            result = service.check_and_pull(
                dry_run=args.dry_run,
                force=args.force,
            )
        
        print(f"\n{'='*60}")
        print("Synchronization Results:")
        print(f"{'='*60}")
        print(f"Mode:              {args.mode}")
        print(f"Total Articles:    {result.total_articles}")
        print(f"Checked:           {result.checked}")
        print(f"Updated:           {result.updated}")
        print(f"Failed:            {result.failed}")
        print(f"Skipped:           {result.skipped}")
        print(f"Timestamp:         {result.timestamp}")
        if result.dataset_path:
            print(f"JSON Dataset:      {result.dataset_path}")
        print(f"{'='*60}\n")
        
        # Pipeline if requested
        if args.pipeline and not args.dry_run and result.updated > 0:
            logger.info("Starting pipeline to codex_digest...")
            pipeline_result = service.pipeline_to_codex_digest()
            print(f"Pipeline Result: {json.dumps(pipeline_result, indent=2)}")
        
        return 0 if result.failed == 0 else 1
        
    except Exception as e:
        logger.error(f"Sync failed: {e}", exc_info=True)
        return 2


